function assemble(items,title,subtitle){
 const tocCount=Math.ceil(items.length/20);
 const firstContent=2+tocCount;
 const foot=(n,total)=>`<footer><span>دليل تشغيل إدارة العهد والأصول | الإصدار 1.1</span><span>صفحة ${n} من ${total}</span></footer>`;
 const total=1+tocCount+items.length;
 const cover=`<section class="sheet cover" id="cover"><header><span>إدارة العهد والأصول</span><span>دليل المستخدم</span></header><h1>${esc(title)}</h1><p class="lead">${esc(subtitle)}</p><div class="tag">خطوات واضحة • أسماء فعلية • أمثلة رقمية</div><div class="meta">الإصدار 1.1<br>تاريخ المراجعة: 12 أكتوبر 2026<br>مرجع: النسخة المحلية الحالية من البرنامج</div><p style="margin-top:14mm;font-size:12pt">للمحاسب المبتدئ والمستخدم التشغيلي ومدير الحسابات والمدير المالي.</p>${foot(1,total)}</section>`;
 let toc='';
 for(let t=0;t<tocCount;t++) toc+=`<section class="sheet toc"><header><span>${esc(title)}</span><span>الفهرس</span></header><h2>${t?'الفهرس - تابع':'فهرس الدليل'}</h2><p class="smallhint">اضغط عنوان الموضوع للانتقال إليه. يمكن البحث في النسخة الرقمية باستخدام Ctrl + F.</p><table><thead><tr><th>الموضوع</th><th>الصفحة</th></tr></thead><tbody>${items.slice(t*20,t*20+20).map((item,j)=>{const i=t*20+j;return `<tr><td><a href="#section-${i}">${esc(item.title)}</a></td><td>${firstContent+i}</td></tr>`}).join('')}</tbody></table>${foot(t+2,total)}</section>`;
 const body=items.map((item,i)=>`<section class="sheet ${item.html.includes('<figure>')?'figure-sheet':''}" id="section-${i}"><header><span>${esc(title)}</span><span>الإصدار 1.1</span></header><h2>${esc(item.title)}</h2><div class="route">${esc(item.route)}</div><main>${item.html}</main>${foot(firstContent+i,total)}</section>`).join('');
 return {html:`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>${esc(title)}</title><style>${css}</style></head><body><nav class="topnav"><a href="#cover">بداية الدليل</a><span>للبحث: Ctrl + F | للطباعة: Ctrl + P</span></nav>${cover}${toc}${body}</body></html>`, total};
}
