const require=createRequire(import.meta.url);
const {chromium}=require('C:/Users/mh/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
// Chromium renders local authored documents only; no app cookies, requests, or UI operations.
const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'});
const renderChecks=[];
try {
 for(const [name,doc] of [['tolan-operating-guide',full],['tolan-quick-guide',short]]){
  const tab=await browser.newPage({viewport:{width:1000,height:1300}});
  await tab.route('**/*',r=>{const url=r.request().url(); return url.startsWith('file:')||url.startsWith('data:')?r.continue():r.abort();});
  await tab.goto(pathToFileURL(path.join(out,`${name}.html`)).href);
  await tab.evaluate(()=>document.fonts.ready);
  await tab.addStyleTag({content:'figure img{max-height:174mm}'});
  // Fit dense pages without allowing clipped content. Keep a readable floor.
  for(let pass=0;pass<2;pass++) await tab.evaluate(()=>{
   for(const sheet of document.querySelectorAll('.sheet:not(.cover)')){
    const main=sheet.querySelector('main');if(!main)continue;
    const bottom=sheet.querySelector('footer').getBoundingClientRect().top-12;
    if(main.getBoundingClientRect().bottom>bottom)sheet.classList.add('dense');
   }
  });
  const overflow=await tab.evaluate(()=>[...document.querySelectorAll('.sheet')].flatMap((sheet,index)=>{
   const main=sheet.querySelector('main')||sheet.querySelector('table');
   const foot=sheet.querySelector('footer');
   return main && main.getBoundingClientRect().bottom>foot.getBoundingClientRect().top-7 ? [{page:index+1,title:sheet.querySelector('h2')?.textContent}]:[];
  }));
  if(overflow.length)throw new Error(`Page overflow: ${JSON.stringify(overflow)}`);
  await fs.writeFile(path.join(out,`${name}.html`),await tab.content(),'utf8');
  await tab.pdf({path:path.join(out,`${name}.pdf`),printBackground:true,preferCSSPageSize:true,tagged:true,outline:true});
  renderChecks.push({name,expectedPages:doc.total,overflow});
  await tab.close();
 }
} finally {await browser.close();}

